import{Base}from"../primitives/Base.js";import{random}from"../tools/random.js";class Bar extends Base{patternToValues(){let values=this.s.split(" ").map(v=>{if("?"!==v)return isFinite(v)?parseInt(v):v});return this.span?Array(this.span).fill().map((_,i)=>values[i%values.length]).slice(0,this.span):values}getCipher(step){return this.fill?random.oneOf(this.steps):this.steps[step]}get s(){return this.getAttribute("s")}set s(value){this.setAttribute("s",value)}get span(){let value=this.getAttribute("span");return value?parseFloat(value):null}set span(value){this.setAttribute("span",value)}get fill(){return this.hasAttribute("fill")}set fill(value){this.toBoolean("fill",value)}get chance(){let value=this.getAttribute("chance");return value?parseFloat(value):null}set chance(value){this.setAttribute("chance",value)}static get observedAttributes(){return["s"]}attributeChangedCallback(name){["s","span"].includes(name)&&(this.steps=this.patternToValues())}}export{Bar};